import type { CourseLesson, CourseQuestion } from './course-types';

/** Original practice bank, informed by DfE programmes. KS3 year allocation is editorial.
 * The five sessions develop a skill through models, fluency, application, reasoning
 * and investigation. Counts describe scheduled practice, not certified coverage. */
export const MATHS_SOURCE = 'https://www.gov.uk/government/publications/national-curriculum-in-england-mathematics-programmes-of-study/national-curriculum-in-england-mathematics-programmes-of-study';

type Kind = 'count' | 'place' | 'compare' | 'round' | 'add' | 'subtract' | 'multiply' | 'divide' | 'bonds' | 'fraction' | 'equivalent' | 'fractionadd' | 'fractioncompare' | 'fractionmultiply' | 'fractiondivide' | 'decimal' | 'decimalcalc' | 'percent' | 'ratio' | 'scale' | 'units' | 'time' | 'money' | 'perimeter' | 'area' | 'volume' | 'shape' | 'solid' | 'angles' | 'turns' | 'position' | 'symmetry' | 'coordinates' | 'data' | 'charts' | 'mean' | 'probability' | 'negative' | 'factors' | 'prime' | 'powers' | 'roman' | 'sequence' | 'algebra' | 'equation' | 'formula' | 'graph' | 'pythagoras' | 'circle' | 'inequality' | 'standard' | 'proportion' | 'transform' | 'congruence' | 'construction' | 'spread' | 'quadratic' | 'simultaneous' | 'order' | 'trig';
type Week = { kind: Kind; title: string; p: number };
type Topic = { domain: string; idea: string; method: string; caution: string; words: [string, string][]; mission: string };
const topic = (domain: string, idea: string, method: string, caution: string, words: [string, string][], mission: string): Topic => ({ domain, idea, method, caution, words, mission });

const TOPICS: Record<Kind, Topic> = {
  count: topic('Number', 'Counting matches one number to each object or step. The last number tells how many.', 'Use a row of dots or a number line. Move one step for each count; skip-counting moves equal jumps.', 'Touch each dot once. Counting backwards reverses the steps.', [['count', 'Say numbers in order to find a total.'], ['step', 'The size of each jump in a number pattern.']], 'Draw a trail of numbered stepping stones and guide a paper explorer forwards and backwards.'),
  place: topic('Number', 'A digit has a different value depending on its place in a number.', 'Make a place-value chart. Moving left makes each place ten times larger; regroup ten smaller units into one larger unit.', 'A zero holds an empty place: 205 has no tens, but the hundreds still stay in their column.', [['digit', 'One of the symbols 0 to 9.'], ['place value', 'The amount a digit represents because of its position.']], 'Design a secret-code number using a place-value chart, then give clues for someone to rebuild it.'),
  compare: topic('Number', 'Numbers can be ordered by comparing the value of the first different place.', 'Line up matching places. Compare from the largest place, or place the numbers on a number line.', 'More digits after a decimal point do not automatically make a larger number.', [['greater than', 'Larger in value.'], ['less than', 'Smaller in value.']], 'Make number cards, arrange them from smallest to largest, and explain one tricky pair.'),
  round: topic('Number', 'Rounding finds a nearby number at a chosen level of accuracy.', 'Find the two neighbouring multiples. Compare distances; at the halfway point round upwards for positive numbers.', 'Name the place you are rounding to. A rounded answer is an estimate, not an exact equality.', [['estimate', 'A useful approximate value.'], ['nearest', 'The value with the smallest distance.']], 'Make a number-line estimate station with exact values and rounded labels, then measure the rounding differences.'),
  add: topic('Arithmetic', 'Addition combines quantities or increases an amount.', 'Partition into useful parts. For written addition, align places and exchange ten units for one unit in the next place.', 'Estimate first, and use subtraction to check the total.', [['sum', 'The result of adding.'], ['exchange', 'Regroup equal values into a different place.']], 'Plan a pretend treasure collection with several piles; calculate totals in two different ways.'),
  subtract: topic('Arithmetic', 'Subtraction can mean taking away or finding the difference between two amounts.', 'Use counting back, counting on, or a written method. Exchange a larger unit when a smaller column needs more units.', 'Subtraction changes when the order changes. Check by adding the difference back.', [['difference', 'The gap between two numbers.'], ['inverse', 'An operation that undoes another operation.']], 'Design a treasure inventory before and after an adventure, then explain how many items changed.'),
  multiply: topic('Arithmetic', 'Multiplication describes equal groups and arrays.', 'Draw rows with the same number in each row. Break a large multiplication into easier products and combine them.', 'The groups must be equal. An array shows why changing the order of two factors keeps the product.', [['factor', 'A number being multiplied.'], ['product', 'The result of multiplication.']], 'Design an array garden on paper; label its rows, columns and total, then split it into two easier arrays.'),
  divide: topic('Arithmetic', 'Division finds the number of equal groups or the amount in each group.', 'Use a matching multiplication fact. For a larger dividend, divide place by place and carry remainders into the next place.', 'A leftover may mean a remainder, a fraction or an extra container: the story decides.', [['dividend', 'The amount being divided.'], ['quotient', 'The result of division.'], ['remainder', 'The amount left after making equal groups.']], 'Draw supplies for equal expedition packs; show sharing, grouping and any leftovers.'),
  bonds: topic('Arithmetic', 'A number bond splits a total into two parts.', 'Draw a part-part-whole model. If one part is known, subtract it from the whole to find the other.', 'The two parts must combine to the whole; use that fact to check.', [['whole', 'The complete amount.'], ['part', 'An amount contained in a whole.']], 'Make a bond rainbow: connect pairs of numbers that form the same total and explain the pattern.'),
  fraction: topic('Fractions', 'A fraction describes equal parts of a whole or equal shares of a quantity.', 'Divide by the denominator to find one equal part, then multiply by the numerator for several parts.', 'The parts must be equal. Always identify what counts as the whole.', [['numerator', 'The top number: how many equal parts are selected.'], ['denominator', 'The bottom number: how many equal parts make the whole.']], 'Draw a picnic tray divided into equal sections; design three fair shares and label their fractions.'),
  equivalent: topic('Fractions', 'Equivalent fractions name the same amount using different-sized equal parts.', 'Multiply or divide the numerator and denominator by the same non-zero number. A strip model makes the unchanged amount visible.', 'Changing only one of the two numbers changes the value.', [['equivalent', 'Equal in value.'], ['simplify', 'Write an equivalent fraction with smaller whole-number parts.']], 'Draw matching fraction strips and create pairs of fraction cards that cover the same length.'),
  fractionadd: topic('Fractions', 'Fractions can be combined when their parts have the same size.', 'Use equivalent fractions to make a common denominator. Add or subtract the numerators, keeping that denominator.', 'Do not add denominators: halves plus halves are still counted in halves.', [['common denominator', 'A shared denominator used to compare or combine fractions.'], ['improper fraction', 'A fraction whose numerator is at least its denominator.']], 'Build a paper recipe from fractional amounts; show how your portions combine into whole units.'),
  fractioncompare: topic('Fractions', 'Comparing fractions means comparing their actual amounts, not just their top numbers.', 'Use equal-length strips, a common denominator, or a common numerator to compare the values.', 'A larger denominator makes each unit fraction smaller.', [['unit fraction', 'A fraction with numerator 1.'], ['compare', 'Decide how values relate to each other.']], 'Create a fraction race on equal-length tracks and explain why each fraction lands in its position.'),
  fractionmultiply: topic('Fractions', 'Multiplying fractions finds a part of a part.', 'Multiply numerators and multiply denominators, then simplify. A rectangle shaded in two directions shows the overlap.', 'Multiplying by a proper fraction makes a positive amount smaller; multiplication does not always make bigger.', [['of', 'In fraction calculations, this often means multiply.'], ['proper fraction', 'A positive fraction smaller than 1.']], 'Draw a rectangular map, shade a fraction of it, then shade a fraction of that region and find the overlap.'),
  fractiondivide: topic('Fractions', 'Sharing a fractional amount into equal groups makes each share smaller.', 'When dividing a fraction by a positive whole number, multiply its denominator by that number, then simplify.', 'Check by multiplying your answer by the number of groups.', [['share', 'Divide an amount into equal parts.'], ['reciprocal', 'A number that multiplies with another to make 1.']], 'Draw a fractional ribbon and divide it fairly between paper characters, keeping the whole ribbon visible.'),
  decimal: topic('Fractions and decimals', 'Decimal places represent tenths, hundredths and thousandths of a unit.', 'Use a place-value chart or a grid. A tenth is 0.1; ten hundredths are also 0.1.', 'Write a zero before the point for values smaller than 1. Trailing zeros do not change a decimal value.', [['decimal point', 'Separates whole-number places from fractional places.'], ['hundredth', 'One of 100 equal parts of a whole.']], 'Design a decimal grid mosaic; label shaded parts as both fractions and decimals.'),
  decimalcalc: topic('Fractions and decimals', 'Decimal calculations use the same place-value structure as whole-number calculations.', 'For addition and subtraction align the decimal points. For scaling, track the value of each digit through a place-value chart.', 'Adding zeros can help align places; they do not change the value.', [['tenths', 'Units each worth one tenth.'], ['scale', 'Multiply or divide by a stated factor.']], 'Build a pretend measurement lab using decimal lengths and record calculations with labelled units.'),
  percent: topic('Percentages', 'A percentage is a number of parts out of 100.', 'Find 10%, 1%, or a useful fraction first. Combine these parts, or multiply the amount by the percentage divided by 100.', 'For a percentage change, calculate the change from the original amount before adding or subtracting it.', [['percent', 'Out of one hundred.'], ['original', 'The starting amount before a change.']], 'Create a pretend shop sale poster showing original prices, percentage changes and final prices.'),
  ratio: topic('Ratio and proportion', 'A ratio compares quantities in a fixed relationship.', 'Count the total number of ratio parts. Divide the total by this number and multiply by each part size.', 'A part-to-part ratio is not the same as a fraction of the whole.', [['ratio', 'A comparison of quantities by multiplication.'], ['ratio part', 'One equal-sized unit in a ratio model.']], 'Design two-colour badges on paper using a fixed colour ratio, and scale the design to a larger batch.'),
  scale: topic('Ratio and proportion', 'Scaling multiplies every matching length or quantity by the same factor.', 'Compare corresponding lengths. A factor of 3 triples lengths; areas then use a factor of 9.', 'Doubling every length does not just double area. State whether you are scaling length, area or volume.', [['scale factor', 'The multiplier connecting corresponding measures.'], ['corresponding', 'Matching positions or measures.']], 'Draw a small and a larger plan of the same pretend room and compare matching measurements.'),
  units: topic('Measurement', 'Measures need a value and a unit. Equivalent units describe the same quantity.', 'Use the conversion relationship: 100 cm = 1 m, 1,000 g = 1 kg, and 1,000 ml = 1 litre.', 'Converting to a smaller unit increases the numerical value; the real amount stays the same.', [['unit', 'A standard amount used to measure.'], ['convert', 'Express the same measure using another unit.']], 'Make a paper museum of labelled pretend lengths, masses and capacities; add matching unit labels.'),
  time: topic('Measurement', 'Time can describe a clock reading or the duration between two events.', 'Count to the next hour, then add remaining minutes. An hour has 60 minutes and a day has 24 hours.', 'A clock uses groups of 60, not groups of 100. Keep morning and afternoon clear.', [['duration', 'How long an event lasts.'], ['timetable', 'A list of events and their times.']], 'Draw an expedition timetable with three events, clock faces and the gaps between them.'),
  money: topic('Measurement', 'Coins and notes represent amounts that can be combined and exchanged.', 'Work in one unit: 100 pence = £1. Add costs, then subtract from the amount paid to find change.', 'Only use pretend purchases here. Equal values can be made with different coin combinations.', [['change', 'Money returned when payment exceeds a cost.'], ['cost', 'The amount paid for something.']], 'Create a pretend stall with paper price tags and calculate several exact payments and changes.'),
  perimeter: topic('Measurement', 'Perimeter is the total distance around a shape.', 'Trace every boundary edge once. A rectangle has two lengths and two widths, so its perimeter is 2 × (length + width).', 'Perimeter measures the outside boundary, not the space inside.', [['perimeter', 'Distance around the boundary.'], ['boundary', 'The outside edge of a shape.']], 'Draw a fenced adventure garden and label every edge, checking that the fence length covers the whole boundary.'),
  area: topic('Measurement', 'Area measures the space inside a two-dimensional shape using square units.', 'Count squares or use a formula. Rectangle: length × width. Triangle: base × perpendicular height ÷ 2.', 'A sloping side is not a perpendicular height. Area needs square units.', [['area', 'The amount of flat space covered.'], ['perpendicular height', 'Height measured at a right angle to the base.']], 'Design a tiled adventure park on squared paper or a hand-drawn grid and compare the areas of different zones.'),
  volume: topic('Measurement', 'Volume measures three-dimensional space using cubic units.', 'A cuboid can be built from layers: length × width gives a layer, and multiplying by height counts all layers.', 'Volume uses cubic units; capacity describes how much a container can hold.', [['volume', 'The space occupied in three dimensions.'], ['cuboid', 'A solid with six rectangular faces.']], 'Sketch storage boxes made from unit cubes, show their layers and compare how many cubes fit.'),
  shape: topic('Geometry', 'Shapes are classified by properties such as sides, angles and parallel edges.', 'Trace the boundary and count sides and corners. A regular polygon has equal sides and equal angles.', 'Turning a shape does not change its name. A square is also a rectangle.', [['polygon', 'A closed flat shape with straight sides.'], ['parallel', 'Lines in the same plane that never meet.'], ['perpendicular', 'Lines meeting at a right angle.']], 'Draw an adventure town built from shapes, label their properties and invent a sorting rule.'),
  solid: topic('Geometry', 'Three-dimensional shapes have properties involving faces, edges and vertices.', 'Count flat faces, line edges and corner vertices systematically. A net unfolds the surface into a flat layout.', 'A circle is flat; a sphere is a solid. Distinguish curved surfaces from flat faces.', [['face', 'A flat surface of a solid.'], ['edge', 'Where two flat faces meet.'], ['vertex', 'A corner where edges meet.']], 'Sketch a robot built from named solids and label the faces, edges and vertices of one part.'),
  angles: topic('Geometry', 'An angle measures a turn between two directions.', 'Use known totals: a straight line is 180°, a whole turn is 360°, and a triangle has angle sum 180°.', 'Diagram size alone is unreliable; use marked facts and explain which total you chose.', [['acute', 'An angle between 0° and 90°.'], ['obtuse', 'An angle between 90° and 180°.'], ['reflex', 'An angle between 180° and 360°.']], 'Draw an angle treasure map and label known and missing turns with the facts used to find them.'),
  turns: topic('Geometry', 'A turn changes direction. Whole, half and quarter turns are fractions of a full rotation.', 'Draw an arrow and turn it around a fixed centre. Clockwise follows clock hands; anticlockwise goes the other way.', 'Keep the centre fixed and distinguish left turns from right turns.', [['clockwise', 'Turning in the direction of clock hands.'], ['quarter turn', 'One of four equal parts of a whole turn.']], 'Move a paper arrow through a route of quarter and half turns; predict its direction before moving it.'),
  position: topic('Geometry', 'Position words describe where objects are compared with other objects.', 'Fix a viewpoint. Trace a route one instruction at a time, checking left, right, above, below and between.', 'Left and right depend on the chosen viewpoint; say whose view you mean.', [['between', 'In the space separating two things.'], ['direction', 'The way an object faces or moves.']], 'Draw a map of an imaginary playground and write directions a paper character can follow.'),
  symmetry: topic('Geometry', 'A line of symmetry divides a shape into matching mirror halves.', 'Imagine folding along the line: every point on one side must match a point on the other at the same distance.', 'A diagonal is not automatically a symmetry line. The halves must match exactly.', [['symmetry', 'A matching relationship under a reflection or rotation.'], ['mirror line', 'The fixed line used for a reflection.']], 'Draw half a badge, finish its mirror half, and mark which folds would make the halves match.'),
  coordinates: topic('Geometry', 'Coordinates locate a point using two ordered values.', 'Move along the horizontal x-axis first, then the vertical y-axis. Negative values go left or down from the origin.', 'The order matters: (2, 5) and (5, 2) are usually different points.', [['origin', 'The point (0, 0).'], ['coordinate', 'A number locating a point along an axis.']], 'Draw a coordinate treasure map with labelled points and write clues that locate the treasure.'),
  data: topic('Statistics', 'Data records information so we can answer a question.', 'Organise values into categories or a tally table. Compare counts, totals and differences using the labels.', 'Describe only what the data supports. A small made-up sample does not represent everyone.', [['data', 'Recorded information.'], ['frequency', 'How many times a value or category appears.']], 'Invent a small survey of fictional characters, record their choices and answer a comparison question.'),
  charts: topic('Statistics', 'Charts show data using consistent scales and clear labels.', 'Read the key before counting symbols, and read axis scales before interpreting bars or lines. Pie charts represent a whole.', 'A symbol may stand for several items. A graph without a fair scale can mislead.', [['scale', 'The amount represented by each interval.'], ['key', 'Explains what a symbol represents.']], 'Turn invented adventure data into a labelled chart and explain one fact and one thing the chart cannot tell you.'),
  mean: topic('Statistics', 'The mean balances a set of values by sharing their total equally.', 'Add all the values and divide by the number of values. A missing value can be found from mean × count.', 'An unusual large value can pull the mean upwards; consider whether it describes the group well.', [['mean', 'Total of values divided by how many values there are.'], ['outlier', 'A value far from the rest of the data.']], 'Invent fair-share scores for a team and show how redistributing the total produces their mean.'),
  probability: topic('Probability', 'Probability describes how likely an event is, from 0 for impossible to 1 for certain.', 'For equally likely outcomes, count favourable outcomes and divide by all possible outcomes. List outcomes systematically.', 'Outcomes must be equally likely for this counting method. Experimental results can differ from predictions.', [['outcome', 'A possible result of an experiment.'], ['sample space', 'The set of all possible outcomes.']], 'Design a fair spinner on paper, list possible outcomes and predict events without needing to gamble.'),
  negative: topic('Number', 'Negative numbers lie below zero on a number line.', 'Track movement through zero. Adding a positive number moves right; subtracting a positive number moves left.', 'A number farther left is smaller. The distance between two numbers is never negative.', [['negative', 'A value smaller than zero.'], ['integer', 'A whole number, including zero and negative whole numbers.']], 'Draw an imaginary temperature trail that crosses zero and annotate every change.'),
  factors: topic('Number', 'Factors divide a number exactly; multiples are produced by multiplying it by whole numbers.', 'List factor pairs. To find a common factor or multiple, compare the lists for both numbers.', 'A factor is no larger than a positive whole number; multiples can keep growing.', [['factor', 'A whole number that divides another without remainder.'], ['multiple', 'A result of multiplication by a whole number.']], 'Design rectangular arrays for a number of dots and use them to collect its factor pairs.'),
  prime: topic('Number', 'A prime number has exactly two positive factors: 1 and itself.', 'Test possible factors systematically. A composite number can be broken into a product of primes.', '1 is not prime. 2 is the only even prime number.', [['prime', 'A whole number greater than 1 with exactly two positive factors.'], ['composite', 'A whole number greater than 1 with more than two positive factors.']], 'Make a number detective board, giving factor evidence for prime and composite suspects.'),
  powers: topic('Number', 'A power records repeated multiplication of the same base.', 'A square is a number multiplied by itself; a cube uses three factors. A root reverses the corresponding power.', '3² is 3 × 3, not 3 × 2. Keep exact roots when a decimal would be approximate.', [['base', 'The number repeatedly multiplied in a power.'], ['exponent', 'The number of equal factors in a positive integer power.']], 'Draw square and cube number models, then record matching powers and roots.'),
  roman: topic('Number', 'Roman numerals use letters with values and rules for combining them.', 'Read groups from left to right. A smaller value before a larger one is subtracted, as in IV and IX.', 'Roman numerals have no zero symbol and do not use our place-value system.', [['numeral', 'A written representation of a number.'], ['Roman numeral', 'A number written with letters such as I, V, X, L and C.']], 'Design an expedition clock or chapter index with Roman numerals and a translation key.'),
  sequence: topic('Algebra', 'A sequence follows a rule connecting its ordered terms.', 'Identify the step between terms, then test the rule on every shown term. A position rule tells you a term directly.', 'A pattern suggested by a few terms is not unique unless a rule is supplied.', [['term', 'One item in a sequence.'], ['nth term', 'A rule giving the value at position n.']], 'Invent a growing tile pattern, record its first terms and describe a rule that predicts a later term.'),
  algebra: topic('Algebra', 'Algebra uses letters to represent values and express relationships.', 'Combine like terms, use distribution over brackets, or substitute a known value. Keep both sides of an equation balanced.', 'Only like terms combine: 2x + 3y is not 5xy.', [['coefficient', 'The number multiplying a variable.'], ['expression', 'A mathematical phrase without an equals sign.'], ['variable', 'A letter representing a value.']], 'Build a paper expression machine and show how several inputs become outputs using the same rule.'),
  equation: topic('Algebra', 'An equation states that two expressions have equal value.', 'Undo operations in reverse order, doing the same operation to both sides. Substitute the solution to check.', 'The goal is to isolate the unknown while preserving equality.', [['equation', 'A statement that two expressions are equal.'], ['solution', 'A value that makes an equation true.']], 'Design a balance puzzle with an unknown treasure weight and solve it with matching actions on both sides.'),
  formula: topic('Algebra', 'A formula links quantities using a general rule.', 'Replace each letter with its value, respecting brackets and operation order. Rearrange by applying inverse operations equally.', 'Write units and identify which letter represents which quantity.', [['formula', 'A rule connecting quantities.'], ['substitute', 'Replace a letter with its given value.']], 'Create a formula card for an imaginary ticket booth or shape, test it on three inputs and explain each letter.'),
  graph: topic('Algebra', 'A graph displays pairs of values that follow a relationship.', 'Calculate coordinate pairs from the rule, choose equal axis scales, and plot each point. For y = mx + c, m is the gradient and c is the y-intercept.', 'Join points only when the relationship between them makes sense.', [['gradient', 'The change in y for a unit increase in x.'], ['intercept', 'Where a graph crosses an axis.']], 'Make an input-output table and plot the points to discover what your rule looks like.'),
  pythagoras: topic('Geometry', 'In a right-angled triangle, the square of the longest side equals the sum of the squares of the other two sides.', 'Identify the hypotenuse, then use a² + b² = c². To find a shorter side, subtract the other square before taking a square root.', 'Pythagoras applies only to right-angled triangles. Do not add the side lengths directly.', [['hypotenuse', 'The side opposite the right angle.'], ['theorem', 'A statement justified by mathematical reasoning.']], 'Draw right-angled triangle gardens and squares on their sides, comparing the square areas.'),
  circle: topic('Geometry', 'A radius joins the centre to the circle; a diameter crosses the centre between opposite points.', 'Diameter = 2 × radius. For older practice, circumference = π × diameter and area = π × radius².', 'Circumference is a length while circle area uses square units. The question will say whether to leave π exact or approximate it.', [['radius', 'Distance from centre to the circle.'], ['diameter', 'A full width through the centre.'], ['circumference', 'Distance around a circle.']], 'Sketch circular parks with labelled centres, radii and diameters, then compare the measures you can find.'),
  inequality: topic('Algebra', 'An inequality compares expressions rather than saying they are exactly equal.', 'Test values or use inverse operations to isolate the variable. Reverse the inequality when multiplying or dividing by a negative number.', 'An inequality often has many solutions. A strict sign excludes its boundary.', [['inequality', 'A comparison using <, >, ≤ or ≥.'], ['boundary', 'A value at the edge of the solution set.']], 'Draw a number-line gate that admits only values meeting your rule and test values on both sides of its boundary.'),
  standard: topic('Number', 'Standard form writes a number as a value from 1 up to 10, multiplied by a power of 10.', 'Count place-value moves. Large numbers use positive powers; numbers smaller than 1 use negative powers.', 'The first factor must be at least 1 and smaller than 10.', [['standard form', 'A × 10ⁿ with 1 ≤ A < 10.'], ['power of ten', 'A multiplier such as 10, 100 or 0.01.']], 'Create an imaginary space museum with very large and small measures written in ordinary and standard form.'),
  proportion: topic('Ratio and proportion', 'Proportional quantities are linked by a constant multiplicative relationship.', 'For direct proportion keep y ÷ x constant. For inverse proportion keep x × y constant; doubling one then halves the other.', 'Check which model fits. A fixed extra cost breaks simple direct proportion.', [['direct proportion', 'Two quantities change by the same scale factor.'], ['inverse proportion', 'Two quantities change with a constant product.']], 'Invent a recipe or equal-work model, make a table of pairs and test whether the chosen relationship stays constant.'),
  transform: topic('Geometry', 'A transformation moves or changes a shape according to a precise rule.', 'Translation adds a vector; reflection makes mirror pairs; rotation turns around a centre; enlargement scales distances from a centre.', 'State the whole rule, including direction, centre or mirror line. Similar shapes may differ in size.', [['translation', 'A slide by the same amount for every point.'], ['reflection', 'A mirror transformation.'], ['enlargement', 'A scaling transformation from a centre.']], 'Draw a badge on a coordinate grid and transform it using two written rules, tracking each vertex.'),
  congruence: topic('Geometry', 'Congruent shapes match exactly in size and shape; similar shapes have equal angles and proportional lengths.', 'Compare corresponding parts. Triangle congruence can use SSS, SAS, ASA or RHS information.', 'Equal angles alone give similarity, not necessarily congruence.', [['congruent', 'Exactly the same size and shape.'], ['similar', 'Matching shape, possibly at a different size.']], 'Draw two matching triangles and one scaled triangle; mark evidence that separates congruence from similarity.'),
  construction: topic('Geometry', 'Geometric construction uses precise rules to build lines and angles.', 'Equal-distance points help find a perpendicular bisector; equal-radius arcs can bisect an angle. Explain the property behind each step.', 'For a paper-only mission sketch and label the reasoning; accurate compass and protractor skills need supervised practical teaching.', [['bisect', 'Divide into two equal parts.'], ['perpendicular bisector', 'A line crossing a segment at its midpoint at a right angle.']], 'Sketch a meeting point equally distant from two camps and explain the perpendicular-bisector property.'),
  spread: topic('Statistics', 'An average describes a typical value while spread describes how varied the values are.', 'Order the data for the median, count frequencies for the mode, and subtract minimum from maximum for the range.', 'Two sets can have the same mean but very different spreads. Association does not prove causation.', [['median', 'The middle value of ordered data, or mean of the two middle values.'], ['range', 'Maximum minus minimum.'], ['mode', 'The most frequent value.']], 'Invent two teams with the same average but different scores and compare their consistency.'),
  quadratic: topic('Algebra', 'A quadratic relationship includes a squared variable.', 'Substitute carefully; to expand two brackets multiply every term in the first by every term in the second and collect like terms.', 'Squaring a negative value gives a positive value. A quadratic graph can give the same output for two inputs.', [['quadratic', 'An expression whose highest variable power is 2.'], ['expand', 'Multiply out brackets into an equivalent expression.']], 'Build a table for a square-number machine, plot positive and negative inputs and inspect the symmetry.'),
  simultaneous: topic('Algebra', 'Two simultaneous equations describe relationships that must hold at the same time.', 'Use one relation to substitute into the other, or eliminate a matching term. Check the resulting pair in both equations.', 'A pair satisfying just one equation is not enough. Graph intersections provide another way to see a shared solution.', [['simultaneous', 'True at the same time.'], ['intersection', 'A point shared by two graphs.']], 'Create a two-clue puzzle for two unknown treasure amounts, then show how the clues narrow to one pair.'),
  order: topic('Arithmetic', 'Operation order makes a calculation unambiguous.', 'Calculate brackets, then powers, then multiplication and division from left to right, then addition and subtraction from left to right.', 'Multiplication does not always precede division; they have equal priority and are processed left to right.', [['brackets', 'Group calculations to be completed first.'], ['priority', 'The order in which operations are performed.']], 'Make two expression cards using the same numbers but different brackets and explain why their totals differ.'),
  trig: topic('Geometry', 'In similar right-angled triangles, ratios of corresponding sides depend on the angle.', 'Relative to an acute angle, label opposite, adjacent and hypotenuse. sin = opposite/hypotenuse, cos = adjacent/hypotenuse, tan = opposite/adjacent.', 'The opposite and adjacent labels change when you choose the other acute angle; the hypotenuse does not.', [['opposite', 'The side across from the chosen angle.'], ['adjacent', 'The side beside the chosen angle, excluding the hypotenuse.']], 'Sketch similar right triangles, label the sides for a chosen angle and compare matching side ratios.'),
};

// p selects a range, unit, shape or level appropriate to the named week.
const week = (kind: Kind, title: string, p = 1): Week => ({ kind, title, p });
const W = week;
