const tidy = (value: number): string => String(Number(value.toFixed(8)));
const gcd = (a: number, b: number): number => b === 0 ? Math.abs(a) : gcd(b, a % b);
const frac = (n: number, d: number): string => { const g = gcd(n, d); return d / g === 1 ? String(n / g) : `${n / g}/${d / g}`; };
const roman = (n: number): string => { let result = ''; for (const [v, s] of [[1000,'M'],[900,'CM'],[500,'D'],[400,'CD'],[100,'C'],[90,'XC'],[50,'L'],[40,'XL'],[10,'X'],[9,'IX'],[5,'V'],[4,'IV'],[1,'I']] as [number,string][]) { while(n >= v) { result += s; n -= v; } } return result; };
function choice(prompt: string, correct: string, wrong: string[], hint: string, explanation: string, seed: number): CourseQuestion {
  const unique = [...new Set(wrong)].filter(x => x !== correct).slice(0, 3);
  if (unique.length < 2) throw new Error(`Not enough distinct alternatives: ${prompt}`);
  const answer = seed % (unique.length + 1);
  const options = [...unique]; options.splice(answer, 0, correct);
  return { prompt, options, answer, hint, explanation };
}
function number(prompt: string, value: number, hint: string, explanation: string, seed: number, suffix = '', step = 1): CourseQuestion {
  const label = (v: number) => `${tidy(v)}${suffix}`;
  return choice(prompt, label(value), [label(value + step),label(value - step),label(value + step * 2)], hint, explanation, seed);
}
