function makeLesson(w: Week, year: number, weekIndex: number, session: number): CourseLesson {
  const t=TOPICS[w.kind];const mode=MODES[session-1];const young=year<=2?YOUNG[w.kind]:undefined;
  const teaching=young?[...young]:[t.idea,t.method,t.caution];
  if(year<=2 && w.kind==='units'){
    teaching[1]=w.p===2?'Use drawn balance pictures to compare pretend objects. Talk about heavier and lighter.':w.p===3?'Use matching drawn cups to compare how much two pretend containers hold.':'Use equal-sized units lined up without gaps. Count and compare the lengths.';
    teaching[2]=w.p===2?'Use the same equal mass units for both objects. A larger total of those units means greater mass.':w.p===3?'Use the same-sized full cups for both containers. More of those cups means a larger capacity.':teaching[2];
  }
  if(year===1 && w.kind==='time'&&w.p===2) teaching.splice(0,3,'We can say what happens before and after another event.','Talk about morning, afternoon and evening. Say what you do first, next and last.','The days of the week follow an order, then start again after Sunday.');
  const questions=Array.from({length:5},(_,index)=>question(w,year,session,index));
  // An extra authored example uses different deterministic values from the practice set.
  const sample=question(w,year,session,8);
  const youngMission=w.kind==='units'&&w.p===2?'Draw a balance for two pretend objects. Label one object as balancing with three equal mass units and the other with five of those same units. Count the units and say which object is heavier and which is lighter.':w.kind==='units'&&w.p===3?'Draw two pretend jugs. Label one as holding three full cups and the other as holding five full cups. Draw every cup the same size. Count the cups and compare the capacities.':year===1&&w.kind==='time'&&w.p===2?'Draw three things in a pretend day. Put them in order: first, next and last.':YOUNG_MISSIONS[w.kind]??t.mission;
  const missionSteps=year<=2?[
    `First 2 minutes: ${youngMission} Use paper and a pencil. A grown-up can help.`,
    `Next 3 minutes: ${['Draw another example. Tell someone what each part shows.','Hide one number. Give a clue and find the number again.','Use your picture in a short pretend adventure.','Show one answer and explain why it works.','Change one thing. Guess what will happen and check it.'][session-1]}`,
    'Final 2 minutes: check by counting, drawing or doing it another way. Tell someone what you found. Take your time.',
  ]:[
    `First 2 minutes: ${t.mission} Use paper and a pencil, or describe your design aloud. For counters use drawn dots or large safe objects, with a grown-up if needed.`,
    `Next 3 minutes: ${mode.mission} Make at least two examples using today's skill.`,
    'Final 2 minutes: check each result with a picture, another method or an inverse calculation. Explain what you changed and what you learned; there is no race.',
  ];
  return {
    id:`maths-y${year}-w${String(weekIndex+1).padStart(2,'0')}-s${session}`,
    subject:'maths',year,week:weekIndex+1,session,
    title:`${w.title} · ${mode.name}`,unit:`${t.domain}: ${w.title}`,
    objective:`${w.title}: ${year<=2?['Draw the idea and talk about it.','Find a missing part and check it.','Use the idea in a pretend story.','Explain one answer and check it.','Change one thing and see what happens.'][session-1]:mode.aim}`,
    teaching:[...teaching,year<=2?['Draw and talk about the idea.','Look for the missing part and check it.','Use the skill in a pretend adventure.','Tell someone why your answer works.','Change one thing and see what happens.'][session-1]:mode.method],
    vocabulary:(year<=2? (YOUNG_WORDS[w.kind]??t.words).slice(0,2).map(([word,meaning])=>({word,meaning})):t.words.map(([word,meaning])=>({word,meaning}))),
    example:{prompt:sample.prompt,explanation:`Answer: ${sample.options[sample.answer]}. ${sample.explanation}`},
    questions,mission:{title:`${w.title}: your paper adventure`,instructions:missionSteps},
    reflection:year<=2?'What did your drawing show? Tell someone how you checked one answer.':`Explain one ${w.title.toLowerCase()} method in your own words. What evidence checks it, and what would change if one value changed?`,
    source:MATHS_SOURCE,
  };
}

export const MATHS_LESSONS: CourseLesson[] = Object.entries(MATHS_YEAR_PLANS).flatMap(([year,weeks])=>weeks.flatMap((w,index)=>Array.from({length:5},(_,session)=>makeLesson(w,Number(year),index,session+1))));
